UPDATE ydsz_flow_join_token
SET join_status = #{targetStatus},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND join_status = #{expectedStatus}
  AND is_deleted = 0

UPDATE ydsz_flow_join_token
SET is_deleted = 1,
    updated_at = CURRENT_TIMESTAMP
WHERE join_status IN

    #{status}

  AND updated_at < #{updatedAtThreshold}
  AND is_deleted = 0
LIMIT #{limit}
